<?= $this->extend('layouts/management') ?><?= $this->section('content') ?>
<form class="surface" method="post" enctype="multipart/form-data" action="<?= site_url('admin/products/'.($product?'update/'.$product['id']:'store')) ?>"><?= csrf_field() ?><div class="form-columns"><div><h2>Informasi Produk</h2><label class="form-label">Nama Produk</label><input class="form-control mb-3" name="name" minlength="3" maxlength="150" required value="<?= esc(old('name',$product['name']??''),'attr') ?>"><label class="form-label">Kategori</label><select class="form-select mb-3" required name="id_category"><option value="">Pilih Kategori</option><?php foreach($categories as $c): ?><option value="<?= esc($c['id'],'attr') ?>" <?= old('id_category',$product['category_id']??'')===$c['id']?'selected':'' ?>><?= esc($c['name']) ?></option><?php endforeach ?></select><label class="form-label">Deskripsi</label><textarea class="form-control mb-3" name="description" rows="6" maxlength="10000"><?= esc(old('description',$product['description']??'')) ?></textarea><div class="row"><div class="col"><label class="form-label">Harga (Rp)</label><input class="form-control" type="number" min="0" max="1000000000" step="1" name="price" required value="<?= esc(old('price',$product['price']??0),'attr') ?>"></div><div class="col"><label class="form-label">Stok</label><input class="form-control" type="number" min="0" max="1000000000" name="stock" required value="<?= esc(old('stock',$product['stock']??0),'attr') ?>"></div></div><label class="form-label mt-3">Status Produk</label><select class="form-select" name="status"><?php foreach(['tersedia'=>'Tersedia','tidak_tersedia'=>'Tidak Tersedia'] as $k=>$v): ?><option value="<?= $k ?>" <?= old('status',($product['status']??'active')==='active'?'tersedia':'tidak_tersedia')===$k?'selected':'' ?>><?= $v ?></option><?php endforeach ?></select></div><div><h2>Gambar Produk</h2><div class="upload-zone"><p>Unggah foto produk</p><input class="form-control" type="file" name="images[]" accept="image/jpeg,image/png,image/webp" multiple id="product-images"><small>JPG, PNG, WEBP · Maksimal 2 MB per gambar · Maksimal 5 gambar per produk.</small></div><div id="preview" class="gallery" aria-live="polite"></div><p class="text-muted mt-3">Gambar pertama menjadi gambar utama. Gambar lama tetap tersimpan saat menambahkan foto baru.</p></div></div><div class="form-actions"><a class="btn btn-light" href="<?= site_url('admin/products') ?>">Kembali</a><button class="btn btn-primary">Simpan Produk</button></div></form>
<?php if($product): ?><section class="surface mt-4"><h2>Galeri Tersimpan</h2><div class="gallery"><?php foreach($images as $im): ?><article><img src="<?= esc($im['image'],'attr') ?>" alt="<?= esc($product['name'],'attr') ?>"><?php if($im['is_primary']): ?><span class="badge text-bg-success">Gambar Utama</span><?php else: ?><form method="post" action="<?= site_url('admin/products/'.$product['id'].'/images/'.$im['id_image'].'/primary') ?>"><?= csrf_field() ?><button class="btn btn-sm btn-outline-primary">Jadikan Utama</button></form><?php endif ?><form method="post" action="<?= site_url('admin/products/'.$product['id'].'/images/'.$im['id_image'].'/delete') ?>" onsubmit="return confirm('Hapus gambar ini?')"><?= csrf_field() ?><button class="btn btn-sm btn-outline-danger">Hapus Gambar</button></form></article><?php endforeach ?><?php if(!$images): ?><p>Belum ada galeri tambahan. Gambar katalog lama tetap digunakan.</p><?php endif ?></div></section><?php endif ?>
<script>document.getElementById('product-images').addEventListener('change',function(){const box=document.getElementById('preview');box.replaceChildren();for(const f of this.files){if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>2097152){const p=document.createElement('p');p.textContent=f.name+': format atau ukuran tidak sesuai.';box.append(p);continue;}const img=document.createElement('img');const u=URL.createObjectURL(f);img.src=u;img.alt='Pratinjau '+f.name;img.onload=()=>URL.revokeObjectURL(u);box.append(img);}});</script><?= $this->endSection() ?>